const port = Number(process.env.PORT ?? 3000);
const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/' && req.method === 'GET') { res.writeHead(200, {'content-type':'text/html; charset=utf-8'}); res.end(uiHtml); return; }
  if (pathname === '/health') {
    if (req.method !== 'GET') return error(res,405,'method_not_allowed','Method not allowed.');
    const row = db.prepare('SELECT heartbeat FROM worker_state WHERE id=1').get() as {heartbeat:number}|undefined;
    return send(res,200,{status:'ok',worker: row && Date.now()-Number(row.heartbeat)<3000 ? 'up':'down'});
  }
  if (pathname === '/api/jobs' && req.method === 'GET') {
    const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as Record<string,unknown>[];
    return send(res,200,{jobs:rows.map(rowToJob)});
  }
  if (pathname === '/api/jobs' && req.method === 'POST') {
    const fields: {field:string;message:string}[] = [];
    const keyHeader = req.headers['idempotency-key'];
    const key = Array.isArray(keyHeader) ? keyHeader[0] : keyHeader;
    if (key !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(key)) fields.push({field:'Idempotency-Key',message:'Must contain 1–128 letters, numbers, underscores, or hyphens.'});
    const contentType = req.headers['content-type'];
    if (!contentType || !/^application\/json(?:\s*;|\s*$)/i.test(contentType)) fields.push({field:'body',message:'Content-Type must be application/json.'});
    let raw = '';
    try { raw = await readBody(req); } catch { fields.push({field:'body',message:'Request body is too large.'}); }
    let parsed: unknown;
    if (raw) { try { parsed = JSON.parse(raw); } catch { fields.push({field:'body',message:'Malformed JSON.'}); } }
    else if (!fields.some(f=>f.field==='body')) fields.push({field:'body',message:'A JSON object is required.'});
    const validated = validate(parsed);
    if ('fields' in validated) fields.push(...validated.fields);
    if (fields.length) return error(res,400,'invalid_request','Request is invalid.',fields);
    const payload = validated as {input:string;steps:number;failAttempts:number};
    const payloadString = JSON.stringify(payload);
    if (key !== undefined) {
      const prior = db.prepare('SELECT payload, job_id FROM idempotency WHERE key=?').get(key) as {payload:string;job_id:string}|undefined;
      if (prior) {
        if (prior.payload !== payloadString) return error(res,409,'idempotency_conflict','This Idempotency-Key was already used with a different payload.');
        const job = getJob(db,prior.job_id); if (job) return send(res,200,job);
      }
    }
    const id = randomUUID(); const now = new Date().toISOString();
    db.exec('BEGIN IMMEDIATE');
    try {
      if (key !== undefined) {
        const prior = db.prepare('SELECT payload, job_id FROM idempotency WHERE key=?').get(key) as {payload:string;job_id:string}|undefined;
        if (prior) {
          db.exec('ROLLBACK');
          if (prior.payload !== payloadString) return error(res,409,'idempotency_conflict','This Idempotency-Key was already used with a different payload.');
          const job=getJob(db,prior.job_id); return job ? send(res,200,job) : error(res,500,'internal_error','Unable to load job.');
        }
      }
      db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at,available_at) VALUES(?,?,?,?,?,0,0,?,?,0)`)
        .run(id,'queued',payload.input,payload.steps,payload.failAttempts,now,now);
      if (key !== undefined) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(key,payloadString,id);
      db.exec('COMMIT');
    } catch (e) { db.exec('ROLLBACK'); throw e; }
    return send(res,201,getJob(db,id));
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
